{"command":"cat << 'EOF' > /tmp/testcargo/Cargo.toml
[package]
name = "testcargo"
version = "0.1.0"
edition = "2021"

[dependencies]
flate2 = "1.1.9"
crc32fast = "1.5.0"
EOF

cat << 'EOF' > /tmp/testcargo/src/main.rs
use flate2::write::ZlibEncoder;
use flate2::Compression;
use std::io::Write;

pub fn encode_png(width: u32, height: u32, rgba_data: &[u8]) -> Vec<u8> {
    let mut png = Vec::new();
    png.extend_from_slice(b"\x89PNG\r\n\x1a\n");

    let mut ihdr_data = Vec::new();
    ihdr_data.extend_from_slice(&width.to_be_bytes());
    ihdr_data.extend_from_slice(&height.to_be_bytes());
    ihdr_data.extend_from_slice(&[8, 6, 0, 0, 0]);
    write_chunk(&mut png, b"IHDR", &ihdr_data);

    let mut raw_scanlines = Vec::with_capacity((height as usize) * (1 + width as usize * 4));
    for y in 0..height as usize {
        raw_scanlines.push(0);
        let row_start = y * (width as usize) * 4;
        let row_end = row_start + (width as usize) * 4;
        raw_scanlines.extend_from_slice(&rgba_data[row_start..row_end]);
    }

    let mut encoder = ZlibEncoder::new(Vec::new(), Compression::default());
    encoder.write_all(&raw_scanlines).unwrap();
    let compressed_data = encoder.finish().unwrap();

    write_chunk(&mut png, b"IDAT", &compressed_data);
    write_chunk(&mut png, b"IEND", &[]);

    png
}

fn write_chunk(buf: &mut Vec<u8>, chunk_type: &[u8; 4], data: &[u8]) {
    buf.extend_from_slice(&(data.len() as u32).to_be_bytes());
    buf.extend_from_slice(chunk_type);
    buf.extend_from_slice(data);
    let mut hasher = crc32fast::Hasher::new();
    hasher.update(chunk_type);
    hasher.update(data);
    let crc = hasher.finalize();
    buf.extend_from_slice(&crc.to_be_bytes());
}

fn main() {
    let width = 100;
    let height = 50;
    let mut pixels = vec![0u8; width * height * 4];
    for i in (0..pixels.len()).step_by(4) {
        pixels[i] = 255;   // R
        pixels[i+1] = 0;   // G
        pixels[i+2] = 0;   // B
        pixels[i+3] = 255; // A
    }
    let png = encode_png(width as u32, height as u32, &pixels);
    std::fs::write("/tmp/test_encoded.png", png).unwrap();
    println!("PNG encoded successfully!");
}
EOF

cd /tmp/testcargo && cargo run --offline 2>&1"}

