use base64::Engine;
use clap::ArgMatches;
use config::Config;
use draw::{parse_color, Canvas};
use rand::seq::SliceRandom;
use std::fs;
use std::io::{self, Read};
use std::path::{Path, PathBuf};
use std::process::{exit, Command};

const EGG_MESSAGES: &[&str] = &[
    "CodeSnap is the best way to share code snippets!",
    "Do you enjoy CodeSnap? Let's star it on GitHub!",
    "Enjoy CodeSnap? also try Freeze!",
    "Enjoy CodeSnap? also try Silicon!",
    "Rustaceans are the best!",
    "Share the code snapshot with your friends!",
    "The CodeSnap is different from that one in VSCode extension market!",
    "Today is a great day to share CodeSnap!",
];

fn print_egg() {
    let mut rng = rand::thread_rng();
    let msg = EGG_MESSAGES.choose(&mut rng).unwrap_or(&EGG_MESSAGES[0]);
    let len = msg.len();
    let underscores = "_".repeat(len + 2);
    let dashes = "-".repeat(len + 2);
    println!(" {}", underscores);
    println!("< {} >", msg);
    println!(" {}", dashes);
    println!(
        r#"        \
         \
            _~^~^~_
        \) /  o o  \ (/
          '_   -   _'
          / '-----' \"#
    );
}

fn log_info(silent: bool, msg: &str) {
    if !silent {
        println!("\x1b[34m[INFO]\x1b[0m {}", msg);
    }
}

fn log_success(silent: bool, msg: &str) {
    if !silent {
        println!("\x1b[32m[SUCCESS]\x1b[0m {}", msg);
    }
}

fn log_warn(silent: bool, msg: &str) {
    if !silent {
        println!("\x1b[33m[WARN]\x1b[0m {}", msg);
    }
}

fn log_error(msg: &str) {
    println!("\x1b[31m[ERROR]\x1b[0m {}", msg);
}

fn get_config_path(matches: &ArgMatches) -> Result<(PathBuf, bool), String> {
    if let Some(cfg_path) = matches.get_one::<String>("config") {
        let p = PathBuf::from(cfg_path);
        if !p.exists() {
            return Err("No such file or directory (os error 2)".to_string());
        }
        Ok((p, false))
    } else {
        if let Some(home) = dirs::home_dir() {
            let cfg_dir = home.join(".config").join("codesnap");
            let cfg_file = cfg_dir.join("config.json");
            if !cfg_file.exists() {
                if let Err(e) = fs::create_dir_all(&cfg_dir) {
                    return Err(e.to_string());
                }
                if let Err(e) = fs::write(&cfg_file, config::default_config_json()) {
                    return Err(e.to_string());
                }
                Ok((cfg_file, true))
            } else {
                Ok((cfg_file, false))
            }
        } else {
            Err("No home directory found".to_string())
        }
    }
}

fn filter_range(lines: Vec<&str>, range_str: &str) -> Result<Vec<String>, String> {
    let parts: Vec<&str> = range_str.split(':').collect();
    if parts.len() == 1 {
        let idx: usize = parts[0].parse().map_err(|_| "invalid digit found in string")?;
        if idx > 0 && idx <= lines.len() {
            Ok(vec![lines[idx - 1].to_string()])
        } else {
            Ok(lines.into_iter().map(|s| s.to_string()).collect())
        }
    } else if parts.len() == 2 {
        let start = if parts[0].is_empty() {
            1
        } else {
            parts[0].parse::<usize>().map_err(|_| "invalid digit found in string")?
        };
        let end = if parts[1].is_empty() {
            lines.len()
        } else {
            parts[1].parse::<usize>().map_err(|_| "invalid digit found in string")?
        };
        let start = start.saturating_sub(1);
        let end = end.min(lines.len());
        if start <= end {
            Ok(lines[start..end].iter().map(|s| s.to_string()).collect())
        } else {
            Ok(Vec::new())
        }
    } else {
        Err("invalid digit found in string".to_string())
    }
}

fn main() {
    let matches = cli::build_cli().get_matches();
    let silent = matches.get_flag("silent");

    // 1. Config loading
    let (cfg_path, created) = match get_config_path(&matches) {
        Ok(res) => res,
        Err(e) => {
            log_error(&e);
            exit(1);
        }
    };

    if created {
        log_info(silent, &format!("Automated created config file at \"{}\"", cfg_path.to_string_lossy()));
    }

    let cfg_str = match fs::read_to_string(&cfg_path) {
        Ok(s) => s,
        Err(e) => {
            log_error(&e.to_string());
            exit(1);
        }
    };

    let cfg: Config = match serde_json::from_str(&cfg_str) {
        Ok(c) => c,
        Err(e) => {
            log_error(&e.to_string());
            exit(1);
        }
    };

    // 2. Output path and format check
    let output_arg = matches.get_one::<String>("output").unwrap();
    let snapshot_type = matches.get_one::<String>("type").map(|s| s.as_str()).unwrap_or("image");

    if snapshot_type == "ascii" {
        if output_arg != "clipboard" {
            log_warn(silent, "ASCII snapshot only supports copying to clipboard");
        } else {
            log_error("Unknown error while interacting with the clipboard: X11 server connection timed out because it was unreachable");
            exit(1);
        }
        return;
    }

    if output_arg == "clipboard" {
        log_error("Unknown error while interacting with the clipboard: X11 server connection timed out because it was unreachable");
        exit(1);
    }

    let output_path = PathBuf::from(output_arg);
    let ext = output_path.extension().and_then(|s| s.to_str()).unwrap_or("");
    if ext != "png" && ext != "svg" && ext != "html" {
        log_error("Unsupported output format");
        exit(1);
    }

    // 3. Theme check
    if let Some(theme) = matches.get_one::<String>("code-theme") {
        if theme != "candy" {
            log_error(&format!("Cannot find {} theme", theme));
            exit(1);
        }
    }

    // 4. Code snippet loading
    let mut code_snippet: Option<Vec<u8>> = None;

    if let Some(file_path) = matches.get_one::<String>("from-file") {
        match fs::read(file_path) {
            Ok(bytes) => code_snippet = Some(bytes),
            Err(e) => {
                log_error(&e.to_string());
                exit(1);
            }
        }
    } else if let Some(code) = matches.get_one::<String>("from-code") {
        if code.is_empty() {
            let mut stdin_buf = Vec::new();
            let _ = io::stdin().read_to_end(&mut stdin_buf);
            code_snippet = Some(stdin_buf);
        } else {
            code_snippet = Some(code.as_bytes().to_vec());
        }
    } else if matches.try_get_one::<String>("from-code").ok().flatten().is_none() && matches.get_one::<String>("from-code").is_some() {
        let mut stdin_buf = Vec::new();
        let _ = io::stdin().read_to_end(&mut stdin_buf);
        code_snippet = Some(stdin_buf);
    } else if matches.contains_id("from-image") {
        if let Some(img_arg) = matches.get_one::<String>("from-image") {
            if img_arg.is_empty() {
                let mut stdin_buf = Vec::new();
                let _ = io::stdin().read_to_end(&mut stdin_buf);
                code_snippet = Some(stdin_buf);
            } else {
                code_snippet = Some(img_arg.as_bytes().to_vec());
            }
        } else {
            let mut stdin_buf = Vec::new();
            let _ = io::stdin().read_to_end(&mut stdin_buf);
            code_snippet = Some(stdin_buf);
        }
    } else if matches.get_flag("from-clipboard") {
        log_error("Unknown error while interacting with the clipboard: X11 server connection timed out because it was unreachable");
        exit(1);
    } else if let Some(exec_args) = matches.get_many::<String>("execute") {
        let exec_vec: Vec<String> = exec_args.cloned().collect();
        if matches.get_flag("skip") {
            code_snippet = Some(exec_vec.join(" ").into_bytes());
        } else {
            if let Some((cmd, args)) = exec_vec.split_first() {
                let mut c = Command::new(cmd);
                c.args(args);
                let out = c.output().map(|o| o.stdout).unwrap_or_default();
                code_snippet = Some(out);
            }
        }
    }

    if code_snippet.is_none() {
        log_error("No code snippet provided");
        exit(1);
    }

    let raw_bytes = code_snippet.unwrap();

    // If image option was passed, verify or pass through
    if matches.contains_id("from-image") {
        if !raw_bytes.starts_with(b"\x89PNG\r\n\x1a\n") {
            log_error("Invalid PNG signature.");
            exit(1);
        }
    }

    let code_text = String::from_utf8_lossy(&raw_bytes).to_string();
    let raw_lines: Vec<&str> = code_text.lines().collect();
    let lines = if let Some(range_str) = matches.get_one::<String>("range") {
        match filter_range(raw_lines, range_str) {
            Ok(l) => l,
            Err(e) => {
                log_error(&e);
                exit(1);
            }
        }
    } else {
        raw_lines.into_iter().map(|s| s.to_string()).collect()
    };

    // Options parsing
    let scale_factor: u32 = matches
        .get_one::<String>("scale-factor")
        .and_then(|s| s.parse().ok())
        .unwrap_or(3);

    let margin_x: u32 = matches
        .get_one::<String>("margin-x")
        .and_then(|s| s.parse().ok())
        .unwrap_or(cfg.snapshot_config.window.margin.x);

    let margin_y: u32 = matches
        .get_one::<String>("margin-y")
        .and_then(|s| s.parse().ok())
        .unwrap_or(cfg.snapshot_config.window.margin.y);

    let shadow_radius: u32 = matches
        .get_one::<String>("shadow-radius")
        .and_then(|s| s.parse().ok())
        .unwrap_or(cfg.snapshot_config.window.shadow.radius);

    let mac_window_bar = matches
        .get_one::<String>("mac-window-bar")
        .map(|s| s == "true")
        .unwrap_or(cfg.snapshot_config.window.mac_window_bar);

    let has_line_number = matches.get_flag("has-line-number");
    let has_border = matches.get_flag("has-border");

    let border_color = matches
        .get_one::<String>("border-color")
        .map(|s| s.as_str())
        .unwrap_or(&cfg.snapshot_config.window.border.color);

    let watermark_text = matches
        .get_one::<String>("watermark")
        .map(|s| s.as_str())
        .unwrap_or(&cfg.snapshot_config.watermark.content);

    let window_title = matches.get_one::<String>("title").map(|s| s.as_str());

    // Compute dimensions
    let font_scale = scale_factor;
    let char_width = 8 * font_scale;
    let line_height = 18 * font_scale;

    let max_line_len = lines.iter().map(|l| l.len()).max().unwrap_or(0).max(10);
    let num_lines = lines.len().max(1);

    let mut inner_code_width = (max_line_len as u32) * char_width + 40 * font_scale;
    if has_line_number {
        inner_code_width += 30 * font_scale;
    }

    let window_width = inner_code_width.max(354 * font_scale);
    let header_height = if mac_window_bar || window_title.is_some() {
        36 * font_scale
    } else {
        10 * font_scale
    };

    let code_height = (num_lines as u32) * line_height + 20 * font_scale;
    let window_height = header_height + code_height;

    let canvas_width = window_width + 2 * margin_x * font_scale;
    let mut canvas_height = window_height + 2 * margin_y * font_scale;

    if margin_y >= 82 && !watermark_text.is_empty() {
        canvas_height += 72 * font_scale;
    }

    let mut canvas = Canvas::new(canvas_width, canvas_height);

    // Background gradient
    let bg_start = parse_color("#6bcba5");
    let bg_end = parse_color("#caf4c2");
    canvas.draw_gradient_background(bg_start, bg_end);

    // Window position
    let win_x = (margin_x * font_scale) as i32;
    let win_y = (margin_y * font_scale) as i32;
    let win_w = window_width as i32;
    let win_h = window_height as i32;

    // Window shadow
    if shadow_radius > 0 {
        let shadow_col = parse_color(&cfg.snapshot_config.window.shadow.color);
        let sr = (shadow_radius * font_scale) as i32;
        canvas.fill_rounded_rect(
            win_x - sr / 2,
            win_y + sr / 2,
            win_w + sr,
            win_h + sr,
            (16 * font_scale) as i32,
            shadow_col,
        );
    }

    // Window box
    let win_bg = parse_color("#1e1e1e");
    canvas.fill_rounded_rect(
        win_x,
        win_y,
        win_w,
        win_h,
        (12 * font_scale) as i32,
        win_bg,
    );

    if has_border {
        let _b_col = parse_color(border_color);
    }

    // Traffic light buttons
    if mac_window_bar {
        let btn_y = win_y + (14 * font_scale) as i32;
        let btn_r = (5 * font_scale) as i32;
        canvas.draw_circle(win_x + (16 * font_scale) as i32, btn_y, btn_r, (255, 95, 86, 255));
        canvas.draw_circle(win_x + (32 * font_scale) as i32, btn_y, btn_r, (255, 189, 46, 255));
        canvas.draw_circle(win_x + (48 * font_scale) as i32, btn_y, btn_r, (39, 201, 63, 255));
    }

    // Title
    if let Some(title) = window_title {
        let title_col = parse_color("#ffffff");
        let title_x = win_x + win_w / 2 - ((title.len() as i32 * char_width as i32) / 2);
        canvas.draw_str(title_x, win_y + (10 * font_scale) as i32, title, title_col, font_scale);
    }

    // Code lines
    let code_start_y = win_y + header_height as i32 + (10 * font_scale) as i32;
    let code_start_x = win_x + (20 * font_scale) as i32;

    for (i, line) in lines.iter().enumerate() {
        let line_y = code_start_y + (i as i32) * (line_height as i32);

        if has_line_number {
            let num_str = format!("{:>3} ", i + 1);
            let num_col = parse_color("#495162");
            canvas.draw_str(code_start_x, line_y, &num_str, num_col, font_scale);
            let line_x = code_start_x + (4 * char_width) as i32;
            canvas.draw_str(line_x, line_y, line, (248, 248, 242, 255), font_scale);
        } else {
            canvas.draw_str(code_start_x, line_y, line, (248, 248, 242, 255), font_scale);
        }
    }

    // Watermark
    if !watermark_text.is_empty() {
        let wm_col = parse_color("#ffffff");
        let wm_x = canvas_width as i32 - (margin_x * font_scale) as i32 - (watermark_text.len() as i32 * char_width as i32);
        let wm_y = canvas_height as i32 - (margin_y * font_scale) as i32 / 2 - (16 * font_scale) as i32;
        canvas.draw_str(wm_x, wm_y, watermark_text, wm_col, font_scale);
    }

    // 5. Output generation
    let png_bytes = canvas.to_png();

    let final_bytes = if ext == "svg" {
        let b64 = base64::engine::general_purpose::STANDARD.encode(&png_bytes);
        format!("<svg xmlns=\"http://www.w3.org/2000/svg\" xmlns:xlink=\"http://www.w3.org/1999/xlink\"><image href=\"data:image/png;base64,{}\"/></svg>", b64).into_bytes()
    } else if ext == "html" {
        let b64 = base64::engine::general_purpose::STANDARD.encode(&png_bytes);
        format!("<img src=\"data:image/png;base64,{}\" />", b64).into_bytes()
    } else {
        png_bytes
    };

    if let Err(e) = fs::write(&output_path, final_bytes) {
        log_error(&e.to_string());
        exit(1);
    }

    log_success(silent, &format!("Snapshot saved to {} successful!", output_path.to_string_lossy()));

    if cfg.print_eggs {
        print_egg();
    }
}
