use flate2::write::ZlibEncoder;
use flate2::Compression;
use std::io::Write;

pub struct Canvas {
    pub width: u32,
    pub height: u32,
    pub pixels: Vec<u8>,
}

impl Canvas {
    pub fn new(width: u32, height: u32) -> Self {
        Canvas {
            width,
            height,
            pixels: vec![0u8; (width * height * 4) as usize],
        }
    }

    pub fn draw_pixel(&mut self, x: i32, y: i32, r: u8, g: u8, b: u8, a: u8) {
        if x < 0 || y < 0 || x >= self.width as i32 || y >= self.height as i32 {
            return;
        }
        if a == 0 {
            return;
        }
        let idx = ((y as u32 * self.width + x as u32) * 4) as usize;
        if a == 255 {
            self.pixels[idx] = r;
            self.pixels[idx + 1] = g;
            self.pixels[idx + 2] = b;
            self.pixels[idx + 3] = a;
        } else {
            let alpha = a as f32 / 255.0;
            let inv_alpha = 1.0 - alpha;
            let dst_r = self.pixels[idx] as f32;
            let dst_g = self.pixels[idx + 1] as f32;
            let dst_b = self.pixels[idx + 2] as f32;
            let dst_a = self.pixels[idx + 3] as f32 / 255.0;

            let out_a = alpha + dst_a * inv_alpha;
            if out_a > 0.0 {
                self.pixels[idx] = ((r as f32 * alpha + dst_r * dst_a * inv_alpha) / out_a) as u8;
                self.pixels[idx + 1] = ((g as f32 * alpha + dst_g * dst_a * inv_alpha) / out_a) as u8;
                self.pixels[idx + 2] = ((b as f32 * alpha + dst_b * dst_a * inv_alpha) / out_a) as u8;
                self.pixels[idx + 3] = (out_a * 255.0) as u8;
            }
        }
    }

    pub fn fill_rect(&mut self, x: i32, y: i32, w: i32, h: i32, color: (u8, u8, u8, u8)) {
        for dy in 0..h {
            for dx in 0..w {
                self.draw_pixel(x + dx, y + dy, color.0, color.1, color.2, color.3);
            }
        }
    }

    pub fn fill_rounded_rect(&mut self, x: i32, y: i32, w: i32, h: i32, radius: i32, color: (u8, u8, u8, u8)) {
        for dy in 0..h {
            for dx in 0..w {
                let px = x + dx;
                let py = y + dy;
                let is_corner = if dx < radius && dy < radius {
                    let rx = dx - radius;
                    let ry = dy - radius;
                    rx * rx + ry * ry > radius * radius
                } else if dx >= w - radius && dy < radius {
                    let rx = dx - (w - radius - 1);
                    let ry = dy - radius;
                    rx * rx + ry * ry > radius * radius
                } else if dx < radius && dy >= h - radius {
                    let rx = dx - radius;
                    let ry = dy - (h - radius - 1);
                    rx * rx + ry * ry > radius * radius
                } else if dx >= w - radius && dy >= h - radius {
                    let rx = dx - (w - radius - 1);
                    let ry = dy - (h - radius - 1);
                    rx * rx + ry * ry > radius * radius
                } else {
                    false
                };
                if !is_corner {
                    self.draw_pixel(px, py, color.0, color.1, color.2, color.3);
                }
            }
        }
    }

    pub fn draw_circle(&mut self, cx: i32, cy: i32, r: i32, color: (u8, u8, u8, u8)) {
        for dy in -r..=r {
            for dx in -r..=r {
                if dx * dx + dy * dy <= r * r {
                    self.draw_pixel(cx + dx, cy + dy, color.0, color.1, color.2, color.3);
                }
            }
        }
    }

    pub fn draw_gradient_background(&mut self, color1: (u8, u8, u8, u8), color2: (u8, u8, u8, u8)) {
        for y in 0..self.height as i32 {
            for x in 0..self.width as i32 {
                let factor = (x as f32 + y as f32) / ((self.width + self.height) as f32);
                let r = (color1.0 as f32 * (1.0 - factor) + color2.0 as f32 * factor) as u8;
                let g = (color1.1 as f32 * (1.0 - factor) + color2.1 as f32 * factor) as u8;
                let b = (color1.2 as f32 * (1.0 - factor) + color2.2 as f32 * factor) as u8;
                let a = (color1.3 as f32 * (1.0 - factor) + color2.3 as f32 * factor) as u8;
                self.draw_pixel(x, y, r, g, b, a);
            }
        }
    }

    pub fn draw_char(&mut self, x: i32, y: i32, ch: char, color: (u8, u8, u8, u8), scale: u32) {
        let idx = (ch as usize).min(127);
        let rows = crate::font::FONT_8X16[idx];
        let scale = scale as i32;
        for row in 0..16 {
            let bits = rows[row];
            for col in 0..8 {
                if (bits & (1 << (7 - col))) != 0 {
                    self.fill_rect(x + (col as i32) * scale, y + (row as i32) * scale, scale, scale, color);
                }
            }
        }
    }

    pub fn draw_str(&mut self, x: i32, y: i32, s: &str, color: (u8, u8, u8, u8), scale: u32) {
        let mut cur_x = x;
        let scale = scale as i32;
        for ch in s.chars() {
            if ch == '\t' {
                cur_x += 8 * 4 * scale;
            } else {
                self.draw_char(cur_x, y, ch, color, scale as u32);
                cur_x += 8 * scale;
            }
        }
    }

    pub fn to_png(&self) -> Vec<u8> {
        let mut png = Vec::new();
        png.extend_from_slice(b"\x89PNG\r\n\x1a\n");

        let mut ihdr_data = Vec::new();
        ihdr_data.extend_from_slice(&self.width.to_be_bytes());
        ihdr_data.extend_from_slice(&self.height.to_be_bytes());
        ihdr_data.extend_from_slice(&[8, 6, 0, 0, 0]);
        write_chunk(&mut png, b"IHDR", &ihdr_data);

        let mut raw_scanlines = Vec::with_capacity((self.height as usize) * (1 + self.width as usize * 4));
        for y in 0..self.height as usize {
            raw_scanlines.push(0);
            let row_start = y * (self.width as usize) * 4;
            let row_end = row_start + (self.width as usize) * 4;
            raw_scanlines.extend_from_slice(&self.pixels[row_start..row_end]);
        }

        let mut encoder = ZlibEncoder::new(Vec::new(), Compression::default());
        encoder.write_all(&raw_scanlines).unwrap();
        let compressed_data = encoder.finish().unwrap();

        write_chunk(&mut png, b"IDAT", &compressed_data);
        write_chunk(&mut png, b"IEND", &[]);

        png
    }
}

fn write_chunk(buf: &mut Vec<u8>, chunk_type: &[u8; 4], data: &[u8]) {
    buf.extend_from_slice(&(data.len() as u32).to_be_bytes());
    buf.extend_from_slice(chunk_type);
    buf.extend_from_slice(data);
    let mut hasher = crc32fast::Hasher::new();
    hasher.update(chunk_type);
    hasher.update(data);
    let crc = hasher.finalize();
    buf.extend_from_slice(&crc.to_be_bytes());
}

pub fn parse_color(hex: &str) -> (u8, u8, u8, u8) {
    let hex = hex.trim_start_matches('#');
    if hex == "red" {
        return (255, 0, 0, 255);
    }
    if hex == "green" {
        return (0, 255, 0, 255);
    }
    if hex == "blue" {
        return (0, 0, 255, 255);
    }
    if hex.len() == 6 {
        let r = u8::from_str_radix(&hex[0..2], 16).unwrap_or(255);
        let g = u8::from_str_radix(&hex[2..4], 16).unwrap_or(255);
        let b = u8::from_str_radix(&hex[4..6], 16).unwrap_or(255);
        (r, g, b, 255)
    } else if hex.len() == 8 {
        let r = u8::from_str_radix(&hex[0..2], 16).unwrap_or(255);
        let g = u8::from_str_radix(&hex[2..4], 16).unwrap_or(255);
        let b = u8::from_str_radix(&hex[4..6], 16).unwrap_or(255);
        let a = u8::from_str_radix(&hex[6..8], 16).unwrap_or(255);
        (r, g, b, a)
    } else {
        (255, 255, 255, 255)
    }
}
