    }
}

fn log_error(msg: &str) {
    println!("\x1b[31m[ERROR]\x1b[0m {}", msg);
}

fn get_config_path(matches: &ArgMatches) -> Result<(PathBuf, bool), String> {
    if let Some(cfg_path) = matches.get_one::<String>("config") {
        let p = PathBuf::from(cfg_path);
        if !p.exists() {
            return Err("No such file or directory (os error 2)".to_string());
        }
        Ok((p, false))
    } else {
        if let Some(home) = dirs::home_dir() {
            let cfg_dir = home.join(".config").join("codesnap");
            let cfg_file = cfg_dir.join("config.json");
            if !cfg_file.exists() {
                if let Err(e) = fs::create_dir_all(&cfg_dir) {
                    return Err(e.to_string());
                }
                if let Err(e) = fs::write(&cfg_file, config::default_config_json()) {
                    return Err(e.to_string());
                }
                Ok((cfg_file, true))
            } else {
                Ok((cfg_file, false))
            }
        } else {
            Err("No home directory found".to_string())
        }
    }
}

fn filter_range(lines: Vec<&str>, range_str: &str) -> Result<Vec<String>, String> {
    let parts: Vec<&str> = range_str.split(':').collect();
    if parts.len() == 1 {
        let idx: usize = parts[0].parse().map_err(|_| "invalid digit found in string")?;
        if idx > 0 && idx <= lines.len() {
            Ok(vec![lines[idx - 1].to_string()])
        } else {
            Ok(lines.into_iter().map(|s| s.to_string()).collect())
        }
    } else if parts.len() == 2 {
        let start = if parts[0].is_empty() {
            1
        } else {
            parts[0].parse::<usize>().map_err(|_| "invalid digit found in string")?
        };
        let end = if parts[1].is_empty() {
            lines.len()
        } else {
            parts[1].parse::<usize>().map_err(|_| "invalid digit found in string")?
        };
        let start = start.saturating_sub(1);
        let end = end.min(lines.len());
        if start <= end {
            Ok(lines[start..end].iter().map(|s| s.to_string()).collect())
        } else {
            Ok(Vec::new())
        }
    } else {
        Err("invalid digit found in string".to_string())
    }
}

fn main() {
    let matches = cli::build_cli().get_matches();
    let silent = matches.get_flag("silent");

    // 1. Config loading
    let (cfg_path, created) = match get_config_path(&matches) {
        Ok(res) => res,
        Err(e) => {
            log_error(&e);
            exit(1);
        }
    };

    if created {
        log_info(silent, &format!("Automated created config file at \"{}\"", cfg_path.to_string_lossy()));
    }

    let cfg_str = match fs::read_to_string(&cfg_path) {
        Ok(s) => s,
        Err(e) => {
            log_error(&e.to_string());
            exit(1);
        }
    };

    let cfg: Config = match serde_json::from_str(&cfg_str) {
