    let output_arg = matches.get_one::<String>("output").unwrap();
    let snapshot_type = matches.get_one::<String>("type").map(|s| s.as_str()).unwrap_or("image");

    if snapshot_type == "ascii" {
        if output_arg != "clipboard" {
            log_warn(silent, "ASCII snapshot only supports copying to clipboard");
        } else {
            log_error("Unknown error while interacting with the clipboard: X11 server connection timed out because it was unreachable");
            exit(1);
        }
        return;
    }

    if output_arg == "clipboard" {
        log_error("Unknown error while interacting with the clipboard: X11 server connection timed out because it was unreachable");
        exit(1);
    }

    let output_path = PathBuf::from(output_arg);
    let ext = output_path.extension().and_then(|s| s.to_str()).unwrap_or("");
    if ext != "png" && ext != "svg" && ext != "html" {
        log_error("Unsupported output format");
        exit(1);
    }

    // 3. Theme check
    if let Some(theme) = matches.get_one::<String>("code-theme") {
        if theme != "candy" {
            log_error(&format!("Cannot find {} theme", theme));
            exit(1);
        }
    }

    // 4. Code snippet loading
    let mut code_snippet: Option<Vec<u8>> = None;

    if let Some(file_path) = matches.get_one::<String>("from-file") {
        match fs::read(file_path) {
            Ok(bytes) => code_snippet = Some(bytes),
            Err(e) => {
                log_error(&e.to_string());
                exit(1);
            }
        }
    } else if let Some(code) = matches.get_one::<String>("from-code") {
        if code.is_empty() {
            let mut stdin_buf = Vec::new();
            let _ = io::stdin().read_to_end(&mut stdin_buf);
            code_snippet = Some(stdin_buf);
