            let _ = io::stdin().read_to_end(&mut stdin_buf);
            code_snippet = Some(stdin_buf);
        }
    } else if matches.get_flag("from-clipboard") {
        log_error("Unknown error while interacting with the clipboard: X11 server connection timed out because it was unreachable");
        exit(1);
    } else if let Some(exec_args) = matches.get_many::<String>("execute") {
        let exec_vec: Vec<String> = exec_args.cloned().collect();
        if matches.get_flag("skip") {
            code_snippet = Some(exec_vec.join(" ").into_bytes());
        } else {
            if let Some((cmd, args)) = exec_vec.split_first() {
                let mut c = Command::new(cmd);
                c.args(args);
                let out = c.output().map(|o| o.stdout).unwrap_or_default();
                code_snippet = Some(out);
            }
        }
    }

