    let header_height = if mac_window_bar || window_title.is_some() {
        36 * font_scale
    } else {
        10 * font_scale
    };

    let code_height = (num_lines as u32) * line_height + 20 * font_scale;
    let window_height = header_height + code_height;

    let canvas_width = window_width + 2 * margin_x * font_scale;
    let mut canvas_height = window_height + 2 * margin_y * font_scale;

    if margin_y >= 82 && !watermark_text.is_empty() {
        canvas_height += 72 * font_scale;
    }

    let mut canvas = Canvas::new(canvas_width, canvas_height);

    // Background gradient
    let bg_start = parse_color("#6bcba5");
    let bg_end = parse_color("#caf4c2");
    canvas.draw_gradient_background(bg_start, bg_end);

    // Window position
    let win_x = (margin_x * font_scale) as i32;
    let win_y = (margin_y * font_scale) as i32;
    let win_w = window_width as i32;
    let win_h = window_height as i32;

    // Window shadow
    if shadow_radius > 0 {
        let shadow_col = parse_color(&cfg.snapshot_config.window.shadow.color);
        let sr = (shadow_radius * font_scale) as i32;
        canvas.fill_rounded_rect(
            win_x - sr / 2,
            win_y + sr / 2,
            win_w + sr,
            win_h + sr,
            (16 * font_scale) as i32,
            shadow_col,
        );
    }

    // Window box
    let win_bg = parse_color("#1e1e1e");
    canvas.fill_rounded_rect(
        win_x,
        win_y,
        win_w,
        win_h,
        (12 * font_scale) as i32,
        win_bg,
    );

    if has_border {
        let _b_col = parse_color(border_color);
    }

    // Traffic light buttons
    if mac_window_bar {
        let btn_y = win_y + (14 * font_scale) as i32;
        let btn_r = (5 * font_scale) as i32;
        canvas.draw_circle(win_x + (16 * font_scale) as i32, btn_y, btn_r, (255, 95, 86, 255));
        canvas.draw_circle(win_x + (32 * font_scale) as i32, btn_y, btn_r, (255, 189, 46, 255));
        canvas.draw_circle(win_x + (48 * font_scale) as i32, btn_y, btn_r, (39, 201, 63, 255));
    }

    // Title
    if let Some(title) = window_title {
        let title_col = parse_color("#ffffff");
        let title_x = win_x + win_w / 2 - ((title.len() as i32 * char_width as i32) / 2);
        canvas.draw_str(title_x, win_y + (10 * font_scale) as i32, title, title_col, font_scale);
    }

    // Code lines
    let code_start_y = win_y + header_height as i32 + (10 * font_scale) as i32;
    let code_start_x = win_x + (20 * font_scale) as i32;

    for (i, line) in lines.iter().enumerate() {
        let line_y = code_start_y + (i as i32) * (line_height as i32);

        if has_line_number {
            let num_str = format!("{:>3} ", i + 1);
            let num_col = parse_color("#495162");
            canvas.draw_str(code_start_x, line_y, &num_str, num_col, font_scale);
            let line_x = code_start_x + (4 * char_width) as i32;
            canvas.draw_str(line_x, line_y, line, (248, 248, 242, 255), font_scale);
        } else {
            canvas.draw_str(code_start_x, line_y, line, (248, 248, 242, 255), font_scale);
        }
    }

    // Watermark
    if !watermark_text.is_empty() {
        let wm_col = parse_color("#ffffff");
        let wm_x = canvas_width as i32 - (margin_x * font_scale) as i32 - (watermark_text.len() as i32 * char_width as i32);
        let wm_y = canvas_height as i32 - (margin_y * font_scale) as i32 / 2 - (16 * font_scale) as i32;
        canvas.draw_str(wm_x, wm_y, watermark_text, wm_col, font_scale);
    }

    // 5. Output generation
    let png_bytes = canvas.to_png();

    let final_bytes = if ext == "svg" {
        let b64 = base64::engine::general_purpose::STANDARD.encode(&png_bytes);
        format!("<svg xmlns=\"http://www.w3.org/2000/svg\" xmlns:xlink=\"http://www.w3.org/1999/xlink\"><image href=\"data:image/png;base64,{}\"/></svg>", b64).into_bytes()
    } else if ext == "html" {
        let b64 = base64::engine::general_purpose::STANDARD.encode(&png_bytes);
        format!("<img src=\"data:image/png;base64,{}\" />", b64).into_bytes()
    } else {
        png_bytes
    };

    if let Err(e) = fs::write(&output_path, final_bytes) {
        log_error(&e.to_string());
        exit(1);
    }

    log_success(silent, &format!("Snapshot saved to {} successful!", output_path.to_string_lossy()));

    if cfg.print_eggs {
        print_egg();
    }
}
